41: struct AntifraudEngine {
42:     max_amount_cents: u64,
43: }
44: 
45: impl AntifraudEngine {
46:     fn new(max_amount_cents: u64) -> Self {
47:         Self { max_amount_cents }
48:     }
49: 
50:     fn evaluate(&self, amount_cents: u64) -> bool {
51:         amount_cents <= self.max_amount_cents
52:     }
53: }
54: 
55: struct PaymentProcessor {
56:     antifraud: AntifraudEngine,
57:     settled_count: AtomicUsize,
58:     rejected_count: AtomicUsize,
59:     total_volume_cents: AtomicU64,
60: }
61: 
62: impl PaymentProcessor {
63:     fn new(max_amount_cents: u64) -> Self {
64:         Self {
65:             antifraud: AntifraudEngine::new(max_amount_cents),
66:             settled_count: AtomicUsize::new(0),
67:             rejected_count: AtomicUsize::new(0),
68:             total_volume_cents: AtomicU64::new(0),
69:         }
70:     }
71: 
72:     fn process(&self, mut tx: PaymentTx) -> PaymentTx {
73:         if !self.antifraud.evaluate(tx.amount_cents) {
74:             tx.status = TxStatus::Rejected;
75:             self.rejected_count.fetch_add(1, Ordering::SeqCst);
76:         } else {
77:             tx.status = TxStatus::Settled;
78:             self.settled_count.fetch_add(1, Ordering::SeqCst);
79:             self.total_volume_cents.fetch_add(tx.amount_cents, Ordering::SeqCst);
80:         }
81:         tx
82:     }
83: }
