8: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
9: pub enum PaymentState {
10:     Initiated,
11:     PendingReview,
12:     Approved,
13:     Settled,
14:     Rejected,
15: }
16: 
17: #[derive(Debug, Clone, PartialEq, Eq)]
18: pub enum PaymentEvent {
19:     RequestReview,
20:     Approve,
21:     Settle,
22:     Reject(String),
23: }
24: 
25: #[derive(Debug, Clone, PartialEq, Eq)]
26: pub struct AuditEntry {
27:     pub tx_id: u64,
28:     pub from_state: PaymentState,
29:     pub to_state: PaymentState,
30:     pub reason: String,
31:     pub timestamp_ms: u64,
32: }
33: 
34: pub struct ApprovalStateMachine {
35:     pub auto_approval_limit_cents: u64,
36:     pub audit_log: Vec<AuditEntry>,
37:     pub processed_count: usize,
38: }
39: 
40: impl ApprovalStateMachine {
41:     pub fn new(auto_approval_limit_cents: u64) -> Self {
42:         Self {
43:             auto_approval_limit_cents,
44:             audit_log: Vec::new(),
45:             processed_count: 0,
46:         }
47:     }
48: 
49:     pub fn evaluate_tx(&mut self, tx_id: u64, amount_cents: u64, clock_ms: u64) -> PaymentState {
50:         self.processed_count += 1;
51:         let (next_state, reason) = if amount_cents <= self.auto_approval_limit_cents {
52:             (PaymentState::Approved, "Automatic threshold validation passed")
53:         } else {
54:             (PaymentState::PendingReview, "Amount exceeds automatic limit")
55:         };
56:         self.log_transition(tx_id, PaymentState::Initiated, next_state, reason, clock_ms);
57:         next_state
58:     }
59: 
60:     pub fn apply_event(
61:         &mut self,
62:         tx_id: u64,
63:         current: PaymentState,
64:         event: PaymentEvent,
65:         clock_ms: u64,
66:     ) -> Result<PaymentState, String> {
67:         let (next, reason) = match (current, event) {
68:             (PaymentState::Initiated, PaymentEvent::RequestReview) => {
69:                 (PaymentState::PendingReview, "Routed to compliance queue".to_string())
70:             }
71:             (PaymentState::PendingReview, PaymentEvent::Approve) => {
72:                 (PaymentState::Approved, "Compliance officer approved".to_string())
73:             }
74:             (PaymentState::Approved, PaymentEvent::Settle) => {
75:                 (PaymentState::Settled, "Settlement executed successfully".to_string())
76:             }
77:             (PaymentState::PendingReview, PaymentEvent::Reject(r)) => {
78:                 (PaymentState::Rejected, format!("Review rejected: {r}"))
79:             }
80:             (PaymentState::Initiated, PaymentEvent::Reject(r)) => {
81:                 (PaymentState::Rejected, format!("Direct rejection: {r}"))
82:             }
83:             (state, ev) => {
84:                 return Err(format!("Illegal state transition from {state:?} via {ev:?}"));
85:             }
86:         };
87:         self.log_transition(tx_id, current, next, &reason, clock_ms);
88:         Ok(next)
89:     }
90: 
91:     fn log_transition(
92:         &mut self,
93:         tx_id: u64,
94:         from_state: PaymentState,
95:         to_state: PaymentState,
96:         reason: &str,
97:         timestamp_ms: u64,
98:     ) {
99:         self.audit_log.push(AuditEntry {
100:             tx_id,
101:             from_state,
102:             to_state,
103:             reason: reason.to_string(),
104:             timestamp_ms,
105:         });
106:     }
107: 
108:     pub fn audit_entries_for(&self, tx_id: u64) -> Vec<AuditEntry> {
109:         self.audit_log
110:             .iter()
111:             .filter(|e| e.tx_id == tx_id)
112:             .cloned()
113:             .collect()
114:     }
115: }
